"""Idempotently populate a separate, explicitly conjectural pilot."""
from construct_lab.etymology import EtymologyStore,SCHEMA
from construct_lab.backup import create_backup
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
s=EtymologyStore(ROOT/'data/construct-lab.sqlite')
create_backup(ROOT/'data/construct-lab.sqlite')
existing=[r[0] for r in s.db.execute('SELECT id FROM projects')]
before={p:s.export(p) for p in existing}
r=s.db.execute("SELECT project FROM etymology_pilots WHERE name='immersiveness'").fetchone()
if r:p=r[0]
else:
 p=s.create_project('Immersiveness — Etymology pilot')
 with s.db:s.db.execute('INSERT INTO etymology_pilots VALUES(?,?)',('immersiveness',p))
def add(kind,values,refs=()):
 content=dict(zip(SCHEMA[kind],values,strict=True))
 for r in s.etymology(p)['records']:
  if r['kind']==kind and r['content']['title']==values[0]:return dict(id=r['id'],version=r['version'])
 d=s.save_etymology(p,dict(kind=kind,content=content,links=list(refs),actor='Assistant — pilot preparation',reason='Seed a sourced linguistic record or explicitly conjectural development example; not researcher approval.',expected_version=0))
 r=d['records'][-1];return dict(id=r['id'],version=r['version'])
a=add('source',['American Heritage: immerse','https://www.ahdictionary.com/word/search.html?q=immerse','To engage wholly or deeply; absorb','The entry connects physical covering in liquid with deep engagement. It traces immerse through Middle English to Latin immergere, with mergere meaning to dip.','English; Latin ancestry reported by dictionary','Modern dictionary account of Middle English and Latin ancestry','immerse entry: senses and etymology; Fifth Edition','2026-10-09','Secondary lexicographic account, not an ancient primary passage. Word ancestry neither fixes modern construct meaning nor proves causality.'])
b=add('source',['Etymonline: immerse','https://www.etymonline.com/word/immerse','Figuratively, of study, work, passion, etc., from 1660s.','Reports early fifteenth-century usage implied in immersed and later figurative use. The progression motivates comparing physical enclosure with attentional engagement.','English; Latin ancestry reported by dictionary','Early fifteenth century; figurative uses reported from 1660s','immerse entry','2026-10-09','Dates are dictionary reports, not independently checked attestations. These dictionaries may share lexical ancestry and are not independent empirical corroboration.'])
i=add('interpretation',['Enclosure as a conceptual possibility','Immersiveness might concern how an environment surrounds a participant.','Move from the physical immersion sense to an analogy about an environment. This is an abductive proposal, not a deduction.','Spatial enclosure could matter in some settings; language history alone cannot establish that it does.','Enclosure may be unnecessary: a book can absorb someone without surrounding them.'],[a])
j=add('interpretation',['Engagement as a conceptual possibility','Immersiveness might concern an experience becoming the dominant frame of attention.','Figurative engagement motivates a candidate psychological interpretation; it does not establish a mechanism or valid scale.','Attention, absorption and presence may overlap and require discriminant tests.','A difficult task may capture attention without producing the experience researchers mean by immersion.'],[a,b])
d1=add('definition',['Candidate A — sensory enclosure','The degree to which a designed environment surrounds a participant with coordinated sensory input.','Environment relative to a participant; proposed environmental property','Coordinated surrounding sensory stimulation.','Attention alone without surrounding sensory input.','An absorbing printed novel would score low despite colloquial immersion.'],[i])
d2=add('definition',['Candidate B — sustained engagement','The degree of sustained allocation of attention to a focal activity or experience.','Participant during an episode; proposed psychological state','Sustained attention to the focal activity.','Momentary attention capture without sustained engagement.','Concentrated spreadsheet work might qualify even if participants reject the term immersion.'],[j])
d3=add('definition',['Candidate C — experiential framing capacity','The capacity of an environment, in relation to a participant and context, to become the dominant experiential frame.','Environment–participant–context relation; proposed capacity','Focal experience organizes perception and interpretation under specified conditions.','Sensory intensity alone; temporary attentional capture alone.','A vivid simulation repeatedly disrupted by external demands may have sensory richness without sustained experiential dominance.'],[i,j])
add('relationship',['Coherence as a proposed antecedent','antecedent','Consistent cues may reduce competing interpretations and support a common experiential frame. Linguistic history does not establish this pathway.','With task demands and content controlled, coherent low-fidelity environments yield greater experienced immersion than rich but inconsistent environments.','Familiarity or ease, rather than coherence, explains the effect.','Randomize coherence and sensory richness independently; measure experienced immersion separately from perceived coherence and task difficulty.'],[d3])
add('relationship',['Competing external demands as a proposed moderator','moderator','External demands may prevent environmental capacity from translating into experienced immersion.','The association between framing capacity and experienced immersion weakens when external interruption demands increase.','Interruptions change frustration or workload, which explains the result.','Factorial experiment manipulating environmental coherence and interruption load; separate frustration, workload and immersion measures.'],[d3])
add('relationship',['Outside-signal detection as a proposed outcome','outcome','A focal frame may reduce processing of task-irrelevant outside signals; this is a testable conjecture.','Higher independently measured experienced immersion predicts slower detection of an external probe at matched workload.','General cognitive load causes both the experience report and slower detection.','Use timed external probes and independent self-report measures; control workload. Do not define immersion by missed probes and then reuse probe misses as validation.'],[d3])
for title,scenario in [('Absorbing book','A reader becomes deeply engaged in a printed novel in an ordinary room.'),('Interrupted simulation','A visually rich surrounding simulation is interrupted repeatedly by mandatory messages.'),('Focused spreadsheet','A participant concentrates intensely on reconciling a spreadsheet without feeling transported into another experiential setting.')]:
 add('case',[title,scenario,'Assistant-authored hypothetical example; not observed research data','development','Use to expose differences between definitions. No gold-standard classification, independent evaluation or empirical support is asserted.'],[d1,d2,d3])
assert all(s.export(x)==before[x] for x in existing if x!=p),'Existing project changed'
print(p);print('Records:',len(s.etymology(p)['records']));print('Other project exports unchanged')
s.close()
